// Package hypertext serves the pipeline editor's pages. Its routes are
// generated by muxt from pages.gohtml; the forms are rendered by
// jsonhandler from definitions in the pipeline schema.
package hypertext

import (
	"context"
	"encoding/json/jsontext"
	"encoding/json/v2"
	"errors"
	"fmt"
	"html/template"
	"log/slog"
	"net/http"
	"net/url"
	"os"
	"strings"
	"sync"

	"github.com/crhntr/jsonschema"
	"github.com/crhntr/jsonschema/jsonhandler"

	"github.com/crhntr/jsonschema/examples/concourse/internal/pipeline"
	"github.com/crhntr/jsonschema/examples/concourse/internal/yamljson"
	"github.com/crhntr/jsonschema/examples/concourse/schema"
)

//go:generate go tool muxt generate --use-receiver-type=Server --output-htmx

// Server is the routes receiver. It holds one pipeline file in memory and,
// when Write is set, saves every change back to it.
type Server struct {
	file  string
	write bool
	log   *slog.Logger

	mu  sync.Mutex
	doc *pipeline.Document

	checker *pipeline.Checker
	forms   map[pipeline.Kind]*jsonschema.Schema // the schema of each kind's form
}

// New returns a Server editing the pipeline in src, which was read from
// file. With write set, changes are saved to file.
func New(ctx context.Context, src []byte, file string, write bool, log *slog.Logger) (*Server, error) {
	doc, err := pipeline.Parse(src)
	if err != nil {
		return nil, fmt.Errorf("reading %s: %w", file, err)
	}
	s := &Server{file: file, write: write, log: log, doc: doc, forms: map[pipeline.Kind]*jsonschema.Schema{}}
	resolved, err := schema.Load(ctx)
	if err != nil {
		return nil, err
	}
	s.checker = pipeline.NewChecker(resolved, schema.Pipeline())
	for _, k := range kinds {
		form, err := jsonhandler.ParseSchemaAt(ctx, schema.Pipeline(), "/$defs/"+k.Definition())
		if err != nil {
			return nil, fmt.Errorf("%s form: %w", k, err)
		}
		s.forms[k] = form
	}
	return s, nil
}

var kinds = []pipeline.Kind{pipeline.Jobs, pipeline.Resources, pipeline.ResourceTypes}

// Routes registers the pages, the form stylesheet and the YAML download.
func Routes(mux *http.ServeMux, s *Server) TemplateRoutePaths {
	paths := TemplateRoutes(mux, s)
	mux.HandleFunc("GET /jsonform.css", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "text/css; charset=utf-8")
		_, _ = w.Write(jsonhandler.Stylesheet())
	})
	mux.HandleFunc("GET /pipeline.yml", func(w http.ResponseWriter, _ *http.Request) {
		text, err := s.current().YAML()
		if err != nil {
			http.Error(w, "the pipeline could not be written as YAML", http.StatusInternalServerError)
			s.log.Error("download", "error", err)
			return
		}
		w.Header().Set("Content-Type", "application/yaml; charset=utf-8")
		w.Header().Set("Content-Disposition", `attachment; filename="pipeline.yml"`)
		_, _ = w.Write(text)
	})
	return paths
}

func (s *Server) current() *pipeline.Document {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.doc
}

// commit replaces the document, and saves it when the server writes.
// Callers hold s.mu.
func (s *Server) commit(d *pipeline.Document) error {
	if s.write {
		text, err := d.YAML()
		if err != nil {
			return err
		}
		info, err := os.Stat(s.file)
		if err != nil {
			return err
		}
		if err := os.WriteFile(s.file, text, info.Mode().Perm()); err != nil {
			return err
		}
	}
	s.doc = d
	return nil
}

// Layout is what every page's frame shows.
type Layout struct {
	File     string
	Write    bool
	Problems int
	Page     string
}

func (s *Server) layout(d *pipeline.Document, page string) Layout {
	return Layout{File: s.file, Write: s.write, Problems: len(s.checker.Check(d)), Page: page}
}

// Overview is the home page: the pipeline graph, its problems, and what it
// is made of.
type Overview struct {
	Layout
	Group    string
	Groups   []pipeline.Group
	Graph    pipeline.Graph
	Invalid  map[string]bool // node IDs with problems
	Problems []Problem
	Lists    []List
}

// Problem is a pipeline problem with a link to where it can be fixed.
type Problem struct {
	pipeline.Problem
	Where, Href string
}

// List is the jobs, resources or resource types.
type List struct {
	Kind  pipeline.Kind
	Title string
	Items []Item
}

// Item is one job, resource or resource type.
type Item struct {
	pipeline.Section
	Problems int
}

// Href is the item's edit page.
func (i Item) Href() string { return sectionHref(i.Kind, i.Name) }

func sectionHref(k pipeline.Kind, name string) string {
	return "/" + string(k) + "/" + url.PathEscape(name)
}

// Overview shows the pipeline, or the jobs of one group.
func (s *Server) Overview(form url.Values) (Overview, error) {
	d := s.current()
	group := form.Get("group")
	problems := s.problems(d)
	o := Overview{
		Layout:   s.layout(d, "overview"),
		Group:    group,
		Groups:   d.Groups(),
		Graph:    d.Graph(group),
		Invalid:  map[string]bool{},
		Problems: problems,
	}
	for _, k := range kinds {
		list := List{Kind: k, Title: title(k)}
		for _, sec := range d.Sections(k) {
			item := Item{Section: sec}
			for _, p := range problems {
				if within(p.Pointer, sec.Pointer) {
					item.Problems++
					o.Invalid[pipeline.Node{Kind: k, Name: sec.Name}.ID()] = true
				}
			}
			list.Items = append(list.Items, item)
		}
		o.Lists = append(o.Lists, list)
	}
	return o, nil
}

// problems checks d and links each problem to the page where it can be
// fixed: the form for its job or resource, or the YAML.
func (s *Server) problems(d *pipeline.Document) []Problem {
	var out []Problem
	for _, p := range s.checker.Check(d) {
		pr := Problem{Problem: p, Where: fmt.Sprintf("line %d", p.Line), Href: fmt.Sprintf("/yaml#L%d", p.Line)}
		for _, k := range kinds {
			for _, sec := range d.Sections(k) {
				if sec.Name != "" && within(p.Pointer, sec.Pointer) {
					pr.Where = fmt.Sprintf("%s %s, line %d", singular(k), sec.Name, p.Line)
					pr.Href = sectionHref(k, sec.Name)
				}
			}
		}
		out = append(out, pr)
	}
	return out
}

// SectionPage edits one job, resource or resource type.
type SectionPage struct {
	Layout
	Kind     pipeline.Kind
	Name     string
	Heading  string
	Line     int
	New      bool
	Form     template.HTML
	YAML     string
	Problems []Problem
}

// SectionResponse answers a request for a section's form: the page with
// the form on it (a first view, an edit, or errors), or where to go after
// a save.
type SectionResponse struct {
	SectionPage
	Location string
	status   int
}

// StatusCode is 422 for a form with errors, otherwise 200.
func (r SectionResponse) StatusCode() int {
	if r.status == 0 {
		return http.StatusOK
	}
	return r.status
}

// Section serves the form for one job, resource or resource type, and
// receives its post.
func (s *Server) Section(request *http.Request, kind, name string) (SectionResponse, error) {
	return s.section(request, kind, name)
}

// NewSection serves an empty form for a new job, resource or resource
// type, and receives its post.
func (s *Server) NewSection(request *http.Request, kind string) (SectionResponse, error) {
	return s.section(request, kind, "")
}

// ValidateSection checks a section's form as it is typed.
func (s *Server) ValidateSection(request *http.Request, kind string) (template.HTML, error) {
	k, err := kindOf(kind)
	if err != nil {
		return "", err
	}
	html, err := jsonhandler.ValidateHTML(request, s.forms[k], nil, s.options(k, request))
	return html, s.fail(err)
}

// section is the page for one section: name is "" for a new one.
func (s *Server) section(r *http.Request, kind, name string) (SectionResponse, error) {
	sp, err := s.spec(kind, name)
	if err != nil {
		return SectionResponse{}, err
	}
	f, err := jsonhandler.Handle(r, s.forms[sp.kind], sp.value(), s.options(sp.kind, r))
	if err != nil {
		return SectionResponse{}, s.fail(err)
	}
	if f.Valid {
		location, err := sp.save(f.Value)
		if err == nil {
			return SectionResponse{Location: location}, nil
		}
		f.Reject(s.fail(err))
	}
	page, err := s.sectionPage(sp, f)
	return SectionResponse{SectionPage: page, status: f.StatusCode()}, err
}

// options are those of a section's form, which checks itself as it is
// typed, at the URL of the page followed by /validate.
func (s *Server) options(k pipeline.Kind, r *http.Request) *jsonhandler.Options {
	return &jsonhandler.Options{
		ID:             k.Definition(),
		SubmitLabel:    "Save",
		Outline:        k == pipeline.Jobs,
		ValidateAction: r.URL.Path + "/validate",
	}
}

// DeleteSection removes a job, resource or resource type.
func (s *Server) DeleteSection(kind, name string) error {
	k, err := kindOf(kind)
	if err != nil {
		return err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	sec, ok := s.doc.Section(k, name)
	if !ok {
		return notFound(fmt.Sprintf("There is no %s named %q.", singular(k), name))
	}
	d, err := s.doc.Remove(sec.Pointer)
	if err != nil {
		return s.fail(err)
	}
	return s.fail(s.commit(d))
}

// spec is a section being edited: what kind, its name ("" for a new one),
// and the document and value it starts from.
type spec struct {
	s    *Server
	kind pipeline.Kind
	name string
	doc  *pipeline.Document
	sec  pipeline.Section
}

func (s *Server) spec(kind, name string) (spec, error) {
	k, err := kindOf(kind)
	if err != nil {
		return spec{}, err
	}
	sp := spec{s: s, kind: k, name: name, doc: s.current()}
	if name != "" {
		sec, ok := sp.doc.Section(k, name)
		if !ok {
			return spec{}, notFound(fmt.Sprintf("There is no %s named %q.", singular(k), name))
		}
		sp.sec = sec
	}
	return sp, nil
}

// value is what the form starts from: the section as it is in the file,
// or nothing for a new one.
func (sp spec) value() jsontext.Value {
	if sp.name == "" {
		return nil
	}
	v, _ := sp.doc.Value(sp.sec.Pointer)
	return v
}

// save puts a valid value in the pipeline: in place of the section, or at
// the end of its list for a new one. It returns the page to go to next.
func (sp spec) save(v jsontext.Value) (string, error) {
	var named struct {
		Name string `json:"name"`
	}
	if err := json.Unmarshal(v, &named); err != nil {
		return "", err
	}
	s := sp.s
	s.mu.Lock()
	defer s.mu.Unlock()
	if other, ok := s.doc.Section(sp.kind, named.Name); ok && (sp.name == "" || other.Name != sp.name) {
		return "", message(fmt.Sprintf("There is already a %s named %q.", singular(sp.kind), named.Name))
	}
	var d *pipeline.Document
	var err error
	if sp.name == "" {
		d, err = s.doc.Append(sp.kind, v)
	} else {
		sec, ok := s.doc.Section(sp.kind, sp.name)
		if !ok {
			return "", message(fmt.Sprintf("The %s %q was renamed or removed while you were editing it.", singular(sp.kind), sp.name))
		}
		d, err = s.doc.Replace(sec.Pointer, v)
	}
	if errors.Is(err, yamljson.ErrShared) {
		return "", message("Part of this " + singular(sp.kind) + " comes from a YAML anchor shared with other parts of the file. Edit it in the YAML instead.")
	}
	if err != nil {
		return "", err
	}
	if err := s.commit(d); err != nil {
		return "", err
	}
	return sectionHref(sp.kind, named.Name), nil
}

func (s *Server) sectionPage(sp spec, f *jsonhandler.Form) (SectionPage, error) {
	html, err := f.HTML()
	if err != nil {
		return SectionPage{}, s.fail(err)
	}
	page := SectionPage{
		Layout: s.layout(sp.doc, string(sp.kind)),
		Kind:   sp.kind,
		Name:   sp.name,
		New:    sp.name == "",
		Form:   html,
	}
	if page.New {
		page.Heading = "New " + singular(sp.kind)
		return page, nil
	}
	page.Heading = sp.name
	page.Line = sp.sec.Line
	if v, err := sp.doc.Value(sp.sec.Pointer); err == nil {
		page.YAML = snippet(v)
	}
	for _, p := range s.problems(sp.doc) {
		if within(p.Pointer, sp.sec.Pointer) {
			page.Problems = append(page.Problems, p)
		}
	}
	return page, nil
}

// SourcePage shows the whole file with its problems on their lines, and a
// text area to edit it.
type SourcePage struct {
	Layout
	Text       string
	Lines      []Line
	Problems   []Problem
	ParseError string
	status     int
}

// StatusCode is 422 when the edited YAML could not be read.
func (p SourcePage) StatusCode() int {
	if p.status == 0 {
		return http.StatusOK
	}
	return p.status
}

// Check is the page's problems, as the live check reports them.
func (p SourcePage) Check() CheckResult {
	return CheckResult{ParseError: p.ParseError, Problems: p.Problems}
}

// Line is one line of the file, with the problems reported on it.
type Line struct {
	N        int
	Text     string
	Problems []string
}

// Source shows the pipeline's YAML.
func (s *Server) Source() (SourcePage, error) {
	d := s.current()
	text, err := d.YAML()
	if err != nil {
		return SourcePage{}, s.fail(err)
	}
	page := SourcePage{Layout: s.layout(d, "yaml"), Text: string(text), Problems: s.problems(d)}
	at := map[int][]string{}
	for _, p := range page.Problems {
		at[p.Line] = append(at[p.Line], p.Message)
	}
	for i, line := range strings.Split(strings.TrimSuffix(page.Text, "\n"), "\n") {
		page.Lines = append(page.Lines, Line{N: i + 1, Text: line, Problems: at[i+1]})
	}
	return page, nil
}

// SaveSource replaces the pipeline with edited YAML. YAML that cannot be
// read is shown again with the reason; YAML with schema problems is saved,
// and its problems shown.
func (s *Server) SaveSource(form url.Values) (SourcePage, error) {
	text := form.Get("yaml")
	d, err := pipeline.Parse([]byte(text))
	if err != nil {
		page := SourcePage{Layout: s.layout(s.current(), "yaml"), Text: text, ParseError: err.Error(), status: http.StatusUnprocessableEntity}
		return page, nil
	}
	s.mu.Lock()
	err = s.commit(d)
	s.mu.Unlock()
	if err != nil {
		return SourcePage{}, s.fail(err)
	}
	return s.Source()
}

// CheckResult is the problems in YAML being typed.
type CheckResult struct {
	ParseError string
	Problems   []Problem
}

// CheckSource checks YAML as it is typed, without saving it.
func (s *Server) CheckSource(form url.Values) CheckResult {
	d, err := pipeline.Parse([]byte(form.Get("yaml")))
	if err != nil {
		return CheckResult{ParseError: err.Error()}
	}
	return CheckResult{Problems: s.problems(d)}
}

// snippet writes a value as YAML.
func snippet(v jsontext.Value) string {
	n, err := yamljson.Encode(v)
	if err != nil {
		return ""
	}
	text, err := yamljson.Format(n)
	if err != nil {
		return ""
	}
	return string(text)
}

func kindOf(s string) (pipeline.Kind, error) {
	for _, k := range kinds {
		if string(k) == s {
			return k, nil
		}
	}
	return "", notFound("There is no such page.")
}

func title(k pipeline.Kind) string {
	switch k {
	case pipeline.Jobs:
		return "Jobs"
	case pipeline.Resources:
		return "Resources"
	}
	return "Resource types"
}

func singular(k pipeline.Kind) string {
	switch k {
	case pipeline.Jobs:
		return "job"
	case pipeline.Resources:
		return "resource"
	}
	return "resource type"
}

// within reports whether ptr is prefix or a location inside it.
func within(ptr, prefix string) bool {
	return ptr == prefix || strings.HasPrefix(ptr, prefix+"/")
}
